-- Optional, non-renewing owner allowance in the existing budget/receipt ledger.
-- Not activated by this migration. No project is seeded, resumed or funded.
-- Deploy migration before the four-argument intent caller. Old callers remain
-- compatible for uncapped projects and fail closed for capped projects.
begin;
alter table public.project_budgets
 add column total_usd_limit_micros bigint,
 add column total_usd_committed_micros bigint not null default 0,
 add column total_approval_sha256 text,
 add constraint project_total_allowance_valid check (
  (total_usd_limit_micros is null and total_usd_committed_micros=0 and total_approval_sha256 is null)
  or (total_usd_limit_micros is not null and total_usd_limit_micros between 1 and 100000000000
   and total_usd_committed_micros between 0 and total_usd_limit_micros
   and total_approval_sha256 is not null and total_approval_sha256 ~ '^[0-9a-f]{64}$'));
alter table public.spend_reservations
 add column total_allowance_micros bigint,
 add column total_allowance_usd_sek numeric,
 add constraint spend_total_allowance_valid check (
  (total_allowance_micros is null and total_allowance_usd_sek is null)
  or (total_allowance_micros is not null and total_allowance_micros>=0
   and total_allowance_usd_sek is not null and total_allowance_usd_sek>0
   and total_allowance_usd_sek not in ('NaN'::numeric,'Infinity'::numeric)));

create or replace function public.project_total_allowance_guard()
returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='DELETE' then
  if old.total_usd_limit_micros is not null then raise exception 'TOTAL_ALLOWANCE_IMMUTABLE' using errcode='55000'; end if;
  return old;
 end if;
 if TG_OP='UPDATE' and old.total_usd_limit_micros is not null and
  (new.project_id is distinct from old.project_id or new.total_usd_limit_micros is distinct from old.total_usd_limit_micros
   or new.total_approval_sha256 is distinct from old.total_approval_sha256
   or new.total_usd_committed_micros<old.total_usd_committed_micros) then
  raise exception 'TOTAL_ALLOWANCE_IMMUTABLE' using errcode='55000';
 end if;
 if (TG_OP='INSERT' and new.total_usd_limit_micros is not null)
  or (TG_OP='UPDATE' and (new.total_usd_limit_micros,new.total_usd_committed_micros,new.total_approval_sha256)
      is distinct from (old.total_usd_limit_micros,old.total_usd_committed_micros,old.total_approval_sha256)) then
  if current_user<>'postgres' then raise exception 'TOTAL_ALLOWANCE_SERVICE_ONLY' using errcode='42501'; end if;
 end if;
 return new;
end $$;
create trigger project_total_allowance_guard before insert or update or delete on public.project_budgets
 for each row execute function public.project_total_allowance_guard();
revoke all on function public.project_total_allowance_guard() from public,anon,authenticated,service_role;

-- Activation only for a paused, owned, not-yet-billed dedicated project.
-- Imported local/other prior ceilings MUST be reconciled by the operator and
-- passed explicitly, never assumed to be zero from absence of native costs.
create or replace function public.budget_set_total_allowance(
 p_project_id uuid,p_owner_id uuid,p_limit_micros bigint,p_prior_committed_micros bigint,p_approval_sha256 text
) returns boolean language plpgsql security definer set search_path='' as $$
declare b public.project_budgets;
begin
 if p_limit_micros is null or p_limit_micros not between 1 and 100000000000
  or p_prior_committed_micros is null or p_prior_committed_micros not between 0 and p_limit_micros
  or p_approval_sha256 is null or p_approval_sha256 !~ '^[0-9a-f]{64}$' then
  raise exception 'INVALID_TOTAL_ALLOWANCE' using errcode='22023';
 end if;
 perform 1 from public.projects where id=p_project_id and owner_id=p_owner_id and execution_paused=true for update;
 if not found then raise exception 'TOTAL_ALLOWANCE_REQUIRES_PAUSED_OWNER' using errcode='42501'; end if;
 select * into b from public.project_budgets where project_id=p_project_id for update;
 if not found or b.total_usd_limit_micros is not null then raise exception 'TOTAL_ALLOWANCE_ALREADY_SET_OR_MISSING' using errcode='55000'; end if;
 if exists(select 1 from public.cost_events where project_id=p_project_id)
  or exists(select 1 from public.spend_reservations where project_id=p_project_id) then
  raise exception 'TOTAL_ALLOWANCE_HISTORY_REQUIRES_RECONCILIATION' using errcode='55000';
 end if;
 update public.project_budgets set total_usd_limit_micros=p_limit_micros,
  total_usd_committed_micros=p_prior_committed_micros,total_approval_sha256=p_approval_sha256,updated_at=now()
  where project_id=p_project_id;
 return true;
end $$;
revoke all on function public.budget_set_total_allowance(uuid,uuid,bigint,bigint,text) from public,anon,authenticated;
grant execute on function public.budget_set_total_allowance(uuid,uuid,bigint,bigint,text) to service_role;

-- Admission and intent are ONE transaction. No race between a separate check
-- and dispatch, and no refund after timeout, release, settlement or month end.
create or replace function public.budget_mark_dispatch_intent(
 p_reservation_id uuid,p_dispatch_token uuid,p_ceiling_basis text,p_usd_sek numeric
) returns boolean language plpgsql security definer set search_path='' as $$
declare v public.spend_reservations; b public.project_budgets; amount numeric;
begin
 if p_reservation_id is null or p_dispatch_token is null then raise exception 'reservation and dispatch token are required' using errcode='22023'; end if;
 if p_ceiling_basis is null or p_ceiling_basis not in ('token_window','fixed_units','internal_fixed') then raise exception 'dispatch intent requires a hard-ceiling basis' using errcode='22023'; end if;
 select * into v from public.spend_reservations where id=p_reservation_id for update;
 if not found or v.status<>'open' then return false; end if;
 select * into b from public.project_budgets where project_id=v.project_id for update;
 if b.total_usd_limit_micros is not null then
  if p_usd_sek is null or p_usd_sek<=0 or p_usd_sek in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) then return false; end if;
  if v.dispatched_at is not null then
   return v.dispatch_token=p_dispatch_token and v.ceiling_basis=p_ceiling_basis
    and v.total_allowance_micros is not null and v.total_allowance_usd_sek=p_usd_sek;
  end if;
  amount=ceil(v.estimated_sek/p_usd_sek*1000000);
  if amount<0 or amount>b.total_usd_limit_micros-b.total_usd_committed_micros then return false; end if;
  update public.project_budgets set total_usd_committed_micros=total_usd_committed_micros+amount::bigint,updated_at=now() where project_id=v.project_id;
 else
  if v.dispatched_at is not null then return v.dispatch_token=p_dispatch_token; end if;
 end if;
 update public.spend_reservations set dispatched_at=now(),dispatch_token=p_dispatch_token,ceiling_basis=p_ceiling_basis,
  total_allowance_micros=case when b.total_usd_limit_micros is not null then amount::bigint else null end,
  total_allowance_usd_sek=case when b.total_usd_limit_micros is not null then p_usd_sek else null end
  where id=p_reservation_id;
 return true;
end $$;
revoke all on function public.budget_mark_dispatch_intent(uuid,uuid,text,numeric) from public,anon,authenticated;
grant execute on function public.budget_mark_dispatch_intent(uuid,uuid,text,numeric) to service_role;

-- Explicit legacy overload: absence of FX is not permission to skip a cap.
create or replace function public.budget_mark_dispatch_intent(
 p_reservation_id uuid,p_dispatch_token uuid,p_ceiling_basis text
) returns boolean language sql security definer set search_path='' as $$
 select public.budget_mark_dispatch_intent(p_reservation_id,p_dispatch_token,p_ceiling_basis,null::numeric);
$$;
revoke all on function public.budget_mark_dispatch_intent(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.budget_mark_dispatch_intent(uuid,uuid,text) to service_role;
comment on column public.project_budgets.total_usd_committed_micros is 'Non-renewing conservative admitted ceilings, not invoices. Never automatically refunded, reset or topped up.';
commit;

-- Human-approved dashboard read: atomic quota reservation and safe audit.
-- No PostHog credentials or provider data are stored.
begin;
create table public.atlas_posthog_read_events (
  event_id uuid primary key default gen_random_uuid(),
  attempt_id uuid not null,
  outcome text not null check (outcome in ('reserved','succeeded','failed')),
  project_id uuid not null references public.projects(id),
  principal_id uuid not null,
  authorization_id uuid not null,
  request_hash text not null check (request_hash ~ '^[a-f0-9]{64}$'),
  occurred_at timestamptz not null default clock_timestamp()
);
create unique index atlas_posthog_read_one_reservation on public.atlas_posthog_read_events(attempt_id) where outcome='reserved';
create unique index atlas_posthog_read_one_outcome on public.atlas_posthog_read_events(attempt_id) where outcome<>'reserved';
create index atlas_posthog_read_quota on public.atlas_posthog_read_events(project_id,occurred_at) where outcome='reserved';
alter table public.atlas_posthog_read_events enable row level security;
revoke all on public.atlas_posthog_read_events from public,anon,authenticated,service_role;
grant select on public.atlas_posthog_read_events to service_role;

create function public.atlas_posthog_read_reject_mutation()
returns trigger language plpgsql set search_path='' as $$
begin raise exception 'posthog_read_audit_immutable' using errcode='23001'; end;
$$;
create trigger atlas_posthog_read_immutable before update or delete or truncate
on public.atlas_posthog_read_events for each statement
execute function public.atlas_posthog_read_reject_mutation();
revoke all on function public.atlas_posthog_read_reject_mutation() from public,anon,authenticated;

create function public.atlas_posthog_reserve_read(
  p_project_id uuid, p_principal_id uuid, p_authorization_id uuid,
  p_request_hash text, p_authorization_event_ids uuid[]
) returns uuid language plpgsql security definer set search_path='' set lock_timeout='2s' as $$
declare
  v_ids uuid[];
  v_now timestamptz;
  v_attempt uuid;
begin
  if p_project_id is null or p_principal_id is null or p_authorization_id is null or
     p_request_hash is null or p_request_hash !~ '^[a-f0-9]{64}$' or
     coalesce(cardinality(p_authorization_event_ids),0) <> 2 then
    raise exception 'posthog_read_not_authorized';
  end if;
  -- Freeze the V1 chain during reservation; this is a short local transaction.
  lock table public.atlas_authorizations in share mode;
  perform 1 from public.projects where id=p_project_id and owner_id=p_principal_id for share;
  if not found then raise exception 'posthog_read_not_authorized'; end if;
  perform pg_advisory_xact_lock(hashtextextended('posthog_read:'||p_project_id::text,0));
  v_now := clock_timestamp();
  select array_agg(event_id order by event_id) into v_ids from public.atlas_authorizations
    where authorization_id=p_authorization_id;
  if v_ids is null or v_ids is distinct from
    (select array_agg(x order by x) from unnest(p_authorization_event_ids) x) or
    (select count(*) from public.atlas_authorizations where authorization_id=p_authorization_id and event_type='requested') <> 1 or
    (select count(*) from public.atlas_authorizations where authorization_id=p_authorization_id and event_type='granted'
       and expires_at > v_now + interval '5 seconds') <> 1 or
    exists (select 1 from public.atlas_authorizations where authorization_id=p_authorization_id and (
      project_id is distinct from p_project_id or principal_id is distinct from p_principal_id or
      authority_basis is distinct from 'founder_owner' or
      action_kind is distinct from 'analytics.posthog.dashboards.read' or
      target_type is distinct from 'posthog_dashboard_read' or
      target_id is distinct from p_project_id::text or target_version_hash is distinct from p_request_hash or
      conditions is distinct from '[]'::jsonb or occurred_at > v_now or event_type not in ('requested','granted')
    )) or
    (select occurred_at from public.atlas_authorizations where authorization_id=p_authorization_id and event_type='requested') >
    (select occurred_at from public.atlas_authorizations where authorization_id=p_authorization_id and event_type='granted') then
    raise exception 'posthog_read_not_authorized';
  end if;
  if (select count(*) from public.atlas_posthog_read_events
      where project_id=p_project_id and outcome='reserved' and occurred_at>v_now-interval '60 seconds') >= 3 or
     (select count(*) from public.atlas_posthog_read_events where project_id=p_project_id and outcome='reserved'
      and occurred_at >= (date_trunc('day',v_now at time zone 'UTC') at time zone 'UTC')) >= 20 then
    raise exception 'posthog_read_quota_exceeded';
  end if;
  v_attempt := gen_random_uuid();
  insert into public.atlas_posthog_read_events(attempt_id,outcome,project_id,principal_id,authorization_id,request_hash)
    values(v_attempt,'reserved',p_project_id,p_principal_id,p_authorization_id,p_request_hash);
  return v_attempt;
end;
$$;
revoke all on function public.atlas_posthog_reserve_read(uuid,uuid,uuid,text,uuid[]) from public,anon,authenticated;
grant execute on function public.atlas_posthog_reserve_read(uuid,uuid,uuid,text,uuid[]) to service_role;

create function public.atlas_posthog_finish_read(p_attempt_id uuid,p_principal_id uuid,p_outcome text)
returns boolean language plpgsql security definer set search_path='' set lock_timeout='2s' as $$
declare v_event public.atlas_posthog_read_events%rowtype; v_prior text;
begin
  if p_attempt_id is null or p_principal_id is null or p_outcome is null or p_outcome not in ('succeeded','failed') then
    raise exception 'posthog_read_invalid_outcome';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('posthog_finish:'||p_attempt_id::text,0));
  select * into v_event from public.atlas_posthog_read_events where attempt_id=p_attempt_id and outcome='reserved';
  if not found or v_event.principal_id is distinct from p_principal_id then raise exception 'posthog_read_unknown_attempt'; end if;
  select outcome into v_prior from public.atlas_posthog_read_events where attempt_id=p_attempt_id and outcome<>'reserved';
  if found then
    if v_prior is distinct from p_outcome then raise exception 'posthog_read_outcome_conflict'; end if;
    return true;
  end if;
  insert into public.atlas_posthog_read_events(attempt_id,outcome,project_id,principal_id,authorization_id,request_hash)
    values(p_attempt_id,p_outcome,v_event.project_id,v_event.principal_id,v_event.authorization_id,v_event.request_hash);
  return true;
end;
$$;
revoke all on function public.atlas_posthog_finish_read(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.atlas_posthog_finish_read(uuid,uuid,text) to service_role;
comment on table public.atlas_posthog_read_events is 'Append-only audit and shared quotas for exact human-approved PostHog metadata reads. No provider data.';
commit;

-- Etapp 1: owner-scoped, immutable prospect evidence. No contact, message or send authority.
begin;

create table public.website_prospects (
 id uuid primary key default gen_random_uuid(),
 project_id uuid not null references public.projects(id) on delete cascade,
 created_by uuid not null references auth.users(id),
 orgnr text not null check (orgnr ~ '^[0-9]{10}$'),
 cfar text not null check (cfar ~ '^[0-9]{1,20}$'),
 current_revision_id uuid,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique (id, project_id), unique (project_id, created_by, cfar)
);
create table public.website_prospect_revisions (
 id uuid primary key default gen_random_uuid(), prospect_id uuid not null, project_id uuid not null,
 number bigint not null check (number > 0), content jsonb not null,
 canonical_content text not null check (octet_length(canonical_content) between 1 and 65536),
 sha256 text not null check (sha256 ~ '^[a-f0-9]{64}$'),
 intent_key text not null check (intent_key ~ '^[A-Za-z0-9_-]{1,100}$'),
 created_at timestamptz not null default now(),
 foreign key (prospect_id, project_id) references public.website_prospects(id, project_id) on delete cascade,
 unique (id, prospect_id, project_id), unique (prospect_id, number), unique (prospect_id, intent_key),
 check (content = canonical_content::jsonb),
 check (sha256 = encode(sha256(convert_to(canonical_content, 'UTF8')), 'hex')),
 check ((content->>'version') = '1'),
 check (content->'company'->>'source' = 'scb'),
 check (jsonb_typeof(content->'improvements') = 'array' and jsonb_array_length(content->'improvements') in (0,3))
);
alter table public.website_prospects add foreign key (current_revision_id, id, project_id)
 references public.website_prospect_revisions(id, prospect_id, project_id);
create table public.website_prospect_decisions (
 id uuid primary key default gen_random_uuid(), prospect_id uuid not null, project_id uuid not null,
 revision_id uuid not null, sha256 text not null check (sha256 ~ '^[a-f0-9]{64}$'),
 reviewed_by uuid not null references auth.users(id), reviewed_at timestamptz not null default now(),
 scope text not null default 'prospect_review' check (scope = 'prospect_review'),
 intent_key text not null check (intent_key ~ '^[A-Za-z0-9_-]{1,100}$'),
 foreign key (revision_id, prospect_id, project_id) references public.website_prospect_revisions(id, prospect_id, project_id),
 unique (prospect_id, revision_id), unique (project_id, reviewed_by, intent_key)
);
create index website_prospect_owner on public.website_prospects(created_by, project_id, updated_at desc);
create index website_prospect_revision_project on public.website_prospect_revisions(project_id);
create index website_prospect_decision_project on public.website_prospect_decisions(project_id);
alter table public.website_prospects enable row level security;
alter table public.website_prospect_revisions enable row level security;
alter table public.website_prospect_decisions enable row level security;
create policy website_prospect_owner_read on public.website_prospects for select to authenticated
 using (created_by = (select auth.uid()) and exists (select 1 from public.projects p where p.id = project_id and p.owner_id = (select auth.uid())));
create policy website_prospect_revision_owner_read on public.website_prospect_revisions for select to authenticated
 using (exists (select 1 from public.website_prospects p where p.id = prospect_id and p.project_id = website_prospect_revisions.project_id and p.created_by = (select auth.uid())));
create policy website_prospect_decision_owner_read on public.website_prospect_decisions for select to authenticated
 using (reviewed_by = (select auth.uid()) and exists (select 1 from public.website_prospects p where p.id = prospect_id and p.project_id = website_prospect_decisions.project_id and p.created_by = (select auth.uid())));
revoke all on public.website_prospects, public.website_prospect_revisions, public.website_prospect_decisions from anon, authenticated;
grant select on public.website_prospects, public.website_prospect_revisions, public.website_prospect_decisions to authenticated;
grant all on public.website_prospects, public.website_prospect_revisions, public.website_prospect_decisions to service_role;

create function public.website_prospect_immutable() returns trigger
 language plpgsql security invoker set search_path = '' as $$
begin raise exception 'PROSPECT_IMMUTABLE' using errcode = '55000'; end $$;
create trigger website_prospect_revision_no_update before update on public.website_prospect_revisions
 for each row execute function public.website_prospect_immutable();
create trigger website_prospect_decision_no_update before update on public.website_prospect_decisions
 for each row execute function public.website_prospect_immutable();

create function public.website_prospect_view(p_principal jsonb, p_input jsonb) returns jsonb
 language plpgsql security invoker set search_path = '' as $$
declare p public.website_prospects; r public.website_prospect_revisions; d public.website_prospect_decisions;
begin
 perform public.website_build_check_access(p_principal, (p_input->>'projectId')::uuid, true);
 select * into strict p from public.website_prospects
 where id = (p_input->>'prospectId')::uuid and project_id = (p_input->>'projectId')::uuid and created_by = (p_principal->>'userId')::uuid;
 select * into strict r from public.website_prospect_revisions where id = p.current_revision_id and prospect_id = p.id and project_id = p.project_id;
 select * into d from public.website_prospect_decisions where prospect_id = p.id and revision_id = r.id and reviewed_by = p.created_by and sha256 = r.sha256;
 return jsonb_build_object('projectId', p.project_id, 'prospectId', p.id, 'revisionId', r.id, 'sha256', r.sha256,
  'number', r.number, 'content', r.content, 'createdAt', p.created_at, 'updatedAt', p.updated_at,
  'approval', case when d.id is null then null else jsonb_build_object('id',d.id,'revisionId',d.revision_id,'sha256',d.sha256,'reviewedBy',d.reviewed_by,'reviewedAt',d.reviewed_at,'scope',d.scope) end);
end $$;

create function public.website_prospect_list(p_principal jsonb, p_input jsonb) returns jsonb
 language plpgsql security invoker set search_path = '' as $$
declare result jsonb;
begin
 perform public.website_build_check_access(p_principal, (p_input->>'projectId')::uuid, true);
 select coalesce(jsonb_agg(public.website_prospect_view(p_principal, jsonb_build_object('projectId',p.project_id,'prospectId',p.id)) order by p.updated_at desc), '[]'::jsonb) into result
 from (select * from public.website_prospects where project_id = (p_input->>'projectId')::uuid and created_by = (p_principal->>'userId')::uuid order by updated_at desc limit 100) p;
 return result;
end $$;

-- Server-only writes. Identity, asset and build references are checked inside the transaction as well.
create function public.website_prospect_save(p_principal jsonb, p_input jsonb) returns jsonb
 language plpgsql security invoker set search_path = '' as $$
declare pid uuid := (p_input->>'projectId')::uuid; uid uuid := (p_principal->>'userId')::uuid;
 p public.website_prospects; r public.website_prospect_revisions; rid uuid;
 c jsonb := p_input->'content'; canonical text := p_input->>'canonicalContent'; key text := p_input->>'idempotencyKey'; image jsonb; improvement jsonb; observation_id text;
begin
 perform public.website_build_check_access(p_principal, pid, true);
 if canonical is null or octet_length(canonical) > 65536 or canonical::jsonb is distinct from c or encode(sha256(convert_to(canonical,'UTF8')),'hex') is distinct from p_input->>'sha256'
  or key is null or key !~ '^[A-Za-z0-9_-]{1,100}$' or c->>'version' is distinct from '1' or c->'company'->>'source' is distinct from 'scb'
  or jsonb_typeof(c->'improvements') is distinct from 'array' then raise exception 'INVALID_PROSPECT' using errcode = '22023'; end if;
 if jsonb_array_length(c->'improvements') not in (0,3) then raise exception 'INVALID_PROSPECT' using errcode = '22023'; end if;
 if p_input->>'prospectId' is null then
  insert into public.website_prospects(project_id,created_by,orgnr,cfar) values(pid,uid,c->'company'->>'orgnr',c->'company'->>'cfar') on conflict(project_id,created_by,cfar) do nothing;
  select * into strict p from public.website_prospects where project_id=pid and created_by=uid and cfar=c->'company'->>'cfar' for update;
 else
  select * into strict p from public.website_prospects where id=(p_input->>'prospectId')::uuid and project_id=pid and created_by=uid for update;
 end if;
 if p.orgnr is distinct from c->'company'->>'orgnr' or p.cfar is distinct from c->'company'->>'cfar' then raise exception 'INVALID_PROSPECT' using errcode='22023'; end if;
 select * into r from public.website_prospect_revisions where prospect_id=p.id and intent_key=key;
 if found then
  if r.sha256 is distinct from p_input->>'sha256' then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505'; end if;
  return public.website_prospect_view(p_principal,jsonb_build_object('projectId',pid,'prospectId',p.id));
 end if;
 if p.current_revision_id is distinct from (p_input->>'expectedRevisionId')::uuid then raise exception 'PROSPECT_STALE' using errcode='55000'; end if;
 if c->'website' is distinct from 'null'::jsonb and (c->'website'->>'verifiedBy')::uuid is distinct from uid then raise exception 'INVALID_PROSPECT' using errcode='22023'; end if;
 if c->'capture' is distinct from 'null'::jsonb then
  if c->'capture'->>'sourceUrl' is distinct from c->'website'->>'url' or jsonb_array_length(c->'capture'->'images') is distinct from 2 then raise exception 'INVALID_PROSPECT' using errcode='22023'; end if;
  for image in select value from jsonb_array_elements(c->'capture'->'images') loop
   if not exists(select 1 from public.assets a where a.id=(image->>'assetId')::uuid and a.project_id=pid and a.kind='image' and a.visibility='internal' and a.status='active' and a.checksum_sha256=image->>'sha256') then raise exception 'INVALID_PROSPECT_ASSET' using errcode='22023'; end if;
  end loop;
 end if;
 for improvement in select value from jsonb_array_elements(c->'improvements') loop
  if jsonb_typeof(improvement->'observationIds') is distinct from 'array' or jsonb_array_length(improvement->'observationIds') not between 1 and 8 then raise exception 'INVALID_PROSPECT' using errcode='22023'; end if;
  for observation_id in select jsonb_array_elements_text(improvement->'observationIds') loop
   if not exists(select 1 from jsonb_array_elements(c->'capture'->'observations') o where o->>'id'=observation_id) then raise exception 'INVALID_PROSPECT_EVIDENCE' using errcode='22023'; end if;
  end loop;
 end loop;
 if c->'design' is distinct from 'null'::jsonb then
  if jsonb_array_length(c->'improvements') <> 3 or not exists(select 1 from public.website_build_plan_revisions plan_revision join public.website_build_plans b on b.id=plan_revision.plan_id and b.project_id=plan_revision.project_id
   where plan_revision.id=(c->'design'->>'revisionId')::uuid and plan_revision.plan_id=(c->'design'->>'planId')::uuid and plan_revision.project_id=pid and plan_revision.sha256=c->'design'->>'sha256' and b.created_by=uid and b.conversation_id=(c->'design'->>'conversationId')::uuid) then raise exception 'INVALID_PROSPECT_DESIGN' using errcode='22023'; end if;
 end if;
 if c->'build' is distinct from 'null'::jsonb then
  if c->'design' = 'null'::jsonb or c->'build'->>'planRevisionId' is distinct from c->'design'->>'revisionId' or not exists(select 1 from public.website_build_sessions s where s.id=(c->'build'->>'sessionId')::uuid and s.project_id=pid and s.created_by=uid and s.plan_revision_id=(c->'design'->>'revisionId')::uuid) then raise exception 'INVALID_PROSPECT_BUILD' using errcode='22023'; end if;
 end if;
 if c->'demo' is distinct from 'null'::jsonb and (c->'build' = 'null'::jsonb or c->'demo'->>'artifactSha256' is distinct from c->'build'->>'sha256') then raise exception 'INVALID_PROSPECT_DEMO' using errcode='22023'; end if;
 insert into public.website_prospect_revisions(prospect_id,project_id,number,content,canonical_content,sha256,intent_key)
 values(p.id,pid,coalesce((select max(number) from public.website_prospect_revisions where prospect_id=p.id),0)+1,c,canonical,p_input->>'sha256',key) returning id into rid;
 update public.website_prospects set current_revision_id=rid,updated_at=now() where id=p.id;
 return public.website_prospect_view(p_principal,jsonb_build_object('projectId',pid,'prospectId',p.id));
end $$;

create function public.website_prospect_approve(p_principal jsonb,p_input jsonb) returns jsonb
 language plpgsql security invoker set search_path='' as $$
declare p public.website_prospects; r public.website_prospect_revisions; d public.website_prospect_decisions; key text:=p_input->>'idempotencyKey'; c jsonb;
begin
 perform public.website_build_check_access(p_principal,(p_input->>'projectId')::uuid,true);
 select * into strict p from public.website_prospects where id=(p_input->>'prospectId')::uuid and project_id=(p_input->>'projectId')::uuid and created_by=(p_principal->>'userId')::uuid for update;
 select * into strict r from public.website_prospect_revisions where id=p.current_revision_id and prospect_id=p.id;
 if r.id is distinct from (p_input->>'revisionId')::uuid or r.sha256 is distinct from p_input->>'sha256' then raise exception 'PROSPECT_STALE' using errcode='55000'; end if;
 c:=r.content;
 if c->'company'->>'inactive' is distinct from 'false' or c->'website' is null or c->'website'='null'::jsonb or c->'capture' is null or c->'capture'='null'::jsonb
  or jsonb_array_length(c->'improvements') is distinct from 3 or c->'design' is null or c->'design'='null'::jsonb or c->'build' is null or c->'build'='null'::jsonb or c->'demo' is null or c->'demo'='null'::jsonb
  or c->'demo'->>'mobileOverflow' is distinct from 'false' or c->'demo'->>'desktopOverflow' is distinct from 'false' then raise exception 'PROSPECT_REVIEW_INCOMPLETE' using errcode='55000'; end if;
 if not exists(select 1 from public.website_build_plans b join public.website_build_mockup_decisions m on m.plan_id=b.id and m.project_id=b.project_id
   where b.id=(c->'design'->>'planId')::uuid and b.current_revision_id=(c->'design'->>'revisionId')::uuid and b.project_id=p.project_id
   and m.id=b.current_mockup_decision_id and m.revision_id=b.current_revision_id and m.approved_by=p.created_by and m.mockup_id=(c->'build'->>'mockupId')::uuid and m.sha256=c->'build'->>'mockupSha256') then raise exception 'PROSPECT_DESIGN_STALE' using errcode='55000'; end if;
 if key is null or key !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode='22023'; end if;
 select * into d from public.website_prospect_decisions where project_id=p.project_id and reviewed_by=p.created_by and intent_key=key;
 if found and (d.prospect_id is distinct from p.id or d.revision_id is distinct from r.id) then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505'; end if;
 insert into public.website_prospect_decisions(prospect_id,project_id,revision_id,sha256,reviewed_by,intent_key) values(p.id,p.project_id,r.id,r.sha256,p.created_by,key) on conflict(prospect_id,revision_id) do nothing;
 return public.website_prospect_view(p_principal,jsonb_build_object('projectId',p.project_id,'prospectId',p.id));
end $$;
do $permissions$
declare f record;
begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'website_prospect_%'
 loop execute format('revoke all on function %s from public,anon,authenticated',f.signature); execute format('grant execute on function %s to service_role',f.signature); end loop;
end $permissions$;
commit;
